program='''def transform(grid):
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    # Contract each connected red diamond by one diagonal step.
    unseen={(r,c) for r in range(h) for c in range(w) if grid[r][c]==2}
    while unseen:
        seed=unseen.pop(); comp={seed}; stack=[seed]
        while stack:
            r,c=stack.pop()
            for dr in (-1,0,1):
                for dc in (-1,0,1):
                    p=(r+dr,c+dc)
                    if p in unseen: unseen.remove(p);comp.add(p);stack.append(p)
        for r,c in comp: out[r][c]=7
        rs=[r for r,c in comp];cs=[c for r,c in comp]
        cr=(min(rs)+max(rs))//2;cc=(min(cs)+max(cs))//2
        radius=(max(rs)-min(rs))//2-1
        if max(cs)-min(cs)==max(rs)-min(rs):
            for r in range(cr-radius,cr+radius+1):
                d=radius-abs(r-cr)
                cols=[cc] if d==0 else [cc-d,cc+d]
                for c in cols:
                    if 0<=r<h and 0<=c<w:out[r][c]=2
        else:
            # Clipped diamonds at a side have a visible flat side.
            radius=(max(rs)-min(rs))//2-1;base=min(cs)+1
            for r in range(cr-radius,cr+radius+1):
                d=radius-abs(r-cr);cols=[base+d] if d==0 else [base+d-1,base+d+1]
                for c in cols:
                    if 0<=r<h and 0<=c<w:out[r][c]=2
    # Expand gray chevrons one step. A singleton expands away from its border.
    gray=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==5]
    if gray:
        rs=[r for r,c in gray];cs=[c for r,c in gray]
        r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
        if len(gray)==1:
            r,c=gray[0]
            if r==0:
                out[r][c-1:c+2]=[5,7,5];out[r+1][c]=5
            elif r==h-1:
                out[r][c-1:c+2]=[5,7,5];out[r-1][c]=5
            elif c==w-1:
                out[r-1][c]=out[r+1][c]=5;out[r][c-1]=5
            else:
                out[r][c-1:c+2]=[5,7,5];out[r+1][c]=5
        elif r1-r0>=c1-c0:
            cr=(r0+r1)//2;radius=(r1-r0)//2+1;base=c0-1
            for r in range(max(0,cr-radius),min(h,cr+radius+1)):
                c=base+radius-abs(r-cr)
                if 0<=c<w:out[r][c]=5
        else:
            cc=(c0+c1)//2;radius=(c1-c0)//2+1;base=r0-1
            for c in range(max(0,cc-radius),min(w,cc+radius+1)):
                r=base+radius-abs(c-cc)
                if 0<=r<h:out[r][c]=5
    return out
'''
